"use strict";(self.webpackChunksparrow_ui_wiki=self.webpackChunksparrow_ui_wiki||[]).push([["764"],{46(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/sparrow-ui-wiki/","label":"\u{1F4D7} Introduction","docId":"intro","unlisted":false},{"type":"category","label":"\u{1F680} Getting Started","collapsed":false,"items":[{"type":"link","href":"/sparrow-ui-wiki/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/getting-started/quick-start","label":"Quick start","docId":"getting-started/quick-start","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/getting-started/concepts","label":"Core concepts and layers","docId":"getting-started/concepts","unlisted":false}],"collapsible":true},{"type":"category","label":"\u{1F4E6} Item","items":[{"type":"link","href":"/sparrow-ui-wiki/item/create","label":"Creating items","docId":"item/create","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/item/render","label":"Rendering and refresh","docId":"item/render","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/item/click","label":"Clicks and guards","docId":"item/click","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F9E9} Pane","items":[{"type":"link","href":"/sparrow-ui-wiki/pane/structure","label":"Character layouts","docId":"pane/structure","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pane/ingredients","label":"Filling content","docId":"pane/ingredients","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pane/composition","label":"Backgrounds, freezing, and nesting","docId":"pane/composition","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pane/programmatic","label":"Programmatic layouts","docId":"pane/programmatic","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F5BC} Window","items":[{"type":"link","href":"/sparrow-ui-wiki/window/lifecycle","label":"Opening and closing","docId":"window/lifecycle","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/layout","label":"Window layouts","docId":"window/layout","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/types","label":"Window types","docId":"window/types","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/title","label":"Window titles","docId":"window/title","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/data","label":"Window data","docId":"window/data","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F9ED} Sessions","items":[{"type":"link","href":"/sparrow-ui-wiki/session/navigation","label":"Submenus and going back","docId":"session/navigation","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/session/structures","label":"The three session structures","docId":"session/structures","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F4C4} Page & Scroll","items":[{"type":"link","href":"/sparrow-ui-wiki/pagination/page","label":"Pagination Page","docId":"pagination/page","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pagination/scroll","label":"Scroll","docId":"pagination/scroll","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pagination/tab","label":"Tab","docId":"pagination/tab","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F392} Inventories","items":[{"type":"link","href":"/sparrow-ui-wiki/inventory/basics","label":"Putting an inventory in a menu","docId":"inventory/basics","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/inventory/virtual","label":"Virtual inventories","docId":"inventory/virtual","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/inventory/referencing","label":"Referenced inventories","docId":"inventory/referencing","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/inventory/rules-events","label":"Access rules and events","docId":"inventory/rules-events","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u2728 Visuals & Animation","items":[{"type":"link","href":"/sparrow-ui-wiki/visual/layers","label":"Visual layers","docId":"visual/layers","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/visual/animation","label":"Animations","docId":"visual/animation","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u26A1 Signal (Optional)","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/why","label":"Why Signals","docId":"signal/why","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/basics","label":"Signal basics","docId":"signal/basics","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/derive","label":"Deriving and combining","docId":"signal/derive","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/async","label":"Async loading","docId":"signal/async","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/polling","label":"Polling","docId":"signal/polling","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/collections","label":"Collection state","docId":"signal/collections","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/partitions","label":"Partition state","docId":"signal/partitions","unlisted":false},{"type":"category","label":"Binding Signals to Menus","items":[{"type":"link","href":"/sparrow-ui-wiki/signal-ui/item","label":"Item display","docId":"signal-ui/item","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/player","label":"Per-player display","docId":"signal-ui/player","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/list","label":"List contents","docId":"signal-ui/list","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/page","label":"Pagination and filtering","docId":"signal-ui/page","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/scroll","label":"Scrolling contents","docId":"signal-ui/scroll","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/tab","label":"Tab selection state","docId":"signal-ui/tab","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/title","label":"Window titles","docId":"signal-ui/title","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/visual","label":"Visual layers","docId":"signal-ui/visual","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F310} Network (Optional)","items":[{"type":"link","href":"/sparrow-ui-wiki/network/listen","label":"Listening to packets","docId":"network/listen","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/network/send-receive","label":"Sending and injecting","docId":"network/send-receive","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F4CE} Additional Notes (Optional)","items":[{"type":"link","href":"/sparrow-ui-wiki/advanced/lifecycle","label":"Object lifecycle and subscriptions","docId":"advanced/lifecycle","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/advanced/transaction","label":"Transactions and concurrency","docId":"advanced/transaction","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/sparrow-ui-wiki/faq","label":"\u2753 FAQ","docId":"faq","unlisted":false}]},"docs":{"advanced/lifecycle":{"id":"advanced/lifecycle","title":"Object lifecycle and subscriptions","description":"After a menu closes, the Window stops displaying, but the Panes, Items, and inventories it references may still serve other menus. What should be kept depends on whether the business still holds it; whether a subscription needs manual shutdown depends on the registration entry.","sidebar":"tutorialSidebar"},"advanced/transaction":{"id":"advanced/transaction","title":"Transactions and concurrency","description":"A player shift-transfers an item from the shared storage into their inventory: the storage must lose it and the inventory must gain it. The library puts the changes across the involved inventories into one transaction, written together on a successful commit; a cancellation or conflict writes none of it.","sidebar":"tutorialSidebar"},"faq":{"id":"faq","title":"\u2753 FAQ","description":"{/ Placeholder. English version is not written yet \u2014 Chinese first, see WIKI-PLAN.md section 13.1. /}","sidebar":"tutorialSidebar"},"getting-started/concepts":{"id":"getting-started/concepts","title":"Core concepts and layers","description":"A Window manages the window, a Pane arranges the layout, and an Element describes what goes in each slot. Panes can nest, and one Window can take several Panes at once.","sidebar":"tutorialSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Compatibility","sidebar":"tutorialSidebar"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick start","description":"A simple welcome menu","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"\u{1F4D7} Introduction","description":"Welcome to the Sparrow UI docs! \u{1F426}","sidebar":"tutorialSidebar"},"inventory/basics":{"id":"inventory/basics","title":"Putting an inventory in a menu","description":"Pane slots can link to an inventory; whatever players put in or take out lives in that inventory. Put, take, drag, shift transfer, double-click collection, and number-key swaps all follow vanilla chest rules, with no click logic to write yourself.","sidebar":"tutorialSidebar"},"inventory/referencing":{"id":"inventory/referencing","title":"Referenced inventories","description":"A ReferencingInventory maps an existing container, such as a chest or a player inventory, into the menu. It stores nothing itself: reads return the mapped container\'s current contents, and writes go straight into the mapped container.","sidebar":"tutorialSidebar"},"inventory/rules-events":{"id":"inventory/rules-events","title":"Access rules and events","description":"Access rules decide whether a player may put items into or take items out of an inventory. Events notify you around every content change: before commit you can cancel or rewrite the change, and after commit you can log it or send a message.","sidebar":"tutorialSidebar"},"inventory/virtual":{"id":"inventory/virtual","title":"Virtual inventories","description":"A VirtualInventory keeps items in memory, fitting slots the menu manages itself: input slots, storages, reward chests. It can cap per-slot stacks, reorder bulk operations, and serialize its contents to a byte array and back.","sidebar":"tutorialSidebar"},"item/click":{"id":"item/click","title":"Clicks and guards","description":"An Item\'s interaction consists of conditional guards and handlers. Guards decide whether the interaction is allowed at all; handlers run after they pass, closing the window, sending a message, and so on.","sidebar":"tutorialSidebar"},"item/create":{"id":"item/create","title":"Creating items","description":"An arrow in a menu can carry information, turn a page, or go back when clicked. Sparrow UI describes a menu item like this with an Item: it decides what to display and what happens when a player interacts with it.","sidebar":"tutorialSidebar"},"item/render":{"id":"item/render","title":"Rendering and refresh","description":"An Item\'s display source can compute its item at display time. When the viewer\'s level, the current time, or a points value in the database changes, a refresh recomputes what is shown.","sidebar":"tutorialSidebar"},"network/listen":{"id":"network/listen","title":"Listening to packets","description":"This network API was built for Sparrow UI\'s own needs and later polished for outside use. It sits near a simplified PacketEvents in feature terms, with the implementation favoring processing efficiency, but it is not treated as absolutely stable.","sidebar":"tutorialSidebar"},"network/send-receive":{"id":"network/send-receive","title":"Sending and injecting","description":"The network API grew out of Sparrow UI\'s own needs and was polished for outside use. It approaches a simplified PacketEvents in capability, with the implementation favoring processing efficiency, but stability is not promised. Prefer the UI APIs for ordinary menu features.","sidebar":"tutorialSidebar"},"pagination/page":{"id":"pagination/page","title":"Pagination Page","description":"When a catalog has more entries than one page can hold, Page splits it across pages. Give it a list and a page size, and buttons can flip to the previous or next page.","sidebar":"tutorialSidebar"},"pagination/scroll":{"id":"pagination/scroll","title":"Scroll","description":"When menu content should be read one row downward or one column rightward at a time, use Scroll. Showing two rows at once, one downward scroll moves the former second row to the top and brings in a fresh row below.","sidebar":"tutorialSidebar"},"pagination/tab":{"id":"pagination/tab","title":"Tab","description":"When a menu has categories like \\"Materials\\" and \\"Tools\\", Tab switches the content of one area in place. Each category maps to a child Pane, each with its own layout and buttons.","sidebar":"tutorialSidebar"},"pane/composition":{"id":"pane/composition","title":"Backgrounds, freezing, and nesting","description":"A Pane\'s background fills the slots that hold no content, and freezing stops a Pane from reacting to player interaction for a while. A Pane can also be nested inside another Pane, or shown in several players\' Windows at once.","sidebar":"tutorialSidebar"},"pane/ingredients":{"id":"pane/ingredients","title":"Filling content","description":"addIngredient binds content to the identifiers in the template. Beyond Items, it can bind inventories, other Panes, or generate content slot by slot.","sidebar":"tutorialSidebar"},"pane/programmatic":{"id":"pane/programmatic","title":"Programmatic layouts","description":"Slots on a Pane can also be filled directly by slot index or coordinate, without a character template, or you can pick an ordered set of slots first and fill them one by one. Once the menu is open, all of these methods remain callable.","sidebar":"tutorialSidebar"},"pane/structure":{"id":"pane/structure","title":"Character layouts","description":"A Pane\'s layout is described with a character template: each string is one row of the menu, each character takes one slot, and slots holding the same character display the same content.","sidebar":"tutorialSidebar"},"session/navigation":{"id":"session/navigation","title":"Submenus and going back","description":"The previous chapters covered building and opening a single Window. A menu with product details, category lists, and other submenus needs to manage moving between and back across several Windows. A WindowSession represents one player\'s session from opening the menu to leaving it: it records how the Windows relate and runs a callback when the whole session ends.","sidebar":"tutorialSidebar"},"session/structures":{"id":"session/structures","title":"The three session structures","description":"Sparrow UI offers three session structures: stack, retained stack, and tree. They differ in which Window a return goes to, and whether the Window you left is kept afterwards.","sidebar":"tutorialSidebar"},"signal-ui/item":{"id":"signal-ui/item","title":"Item display","description":"In the purchase menu, the player clicks the diamond and the quantity rises by one each time. The button\'s name starts at \\"Quantity 2\\" after the click. The quantity belongs to this menu open alone, so the menu creates a plain Signal at build time.","sidebar":"tutorialSidebar"},"signal-ui/list":{"id":"signal-ui/list","title":"List contents","description":"When an admin lists diamonds, an already open catalog should gain an item right away. A group of slots changes together here, so bind the list with addIngredient.","sidebar":"tutorialSidebar"},"signal-ui/page":{"id":"signal-ui/page","title":"Pagination and filtering","description":"The arrows in Pagination Page always look usable. This time the previous arrow grays out on the first page, the next on the last, and a \\"1 / 2\\" style page number sits in the middle.","sidebar":"tutorialSidebar"},"signal-ui/player":{"id":"signal-ui/player","title":"Per-player display","description":"Alice picks two in the shop while Bob stays at one, and both can share the same Item. The difference is that the dependency is now a player partition: the provider reads the current viewer\'s value, and a click updates the clicker\'s partition.","sidebar":"tutorialSidebar"},"signal-ui/scroll":{"id":"signal-ui/scroll","title":"Scrolling contents","description":"A scrolling menu takes a ListSignal directly. Twelve diamond stacks below sit in three columns, two rows visible at a time. One click of the down button moves the visible range from stacks 1-6 to 4-9, and the button\'s row number updates with it.","sidebar":"tutorialSidebar"},"signal-ui/tab":{"id":"signal-ui/tab","title":"Tab selection state","description":"A category menu has to switch content and mark the active category. Tab.selected() exposes a Signal for the selected key, and buttons that depend on it can change their names.","sidebar":"tutorialSidebar"},"signal-ui/title":{"id":"signal-ui/title","title":"Window titles","description":"Sometimes the player\'s chosen quantity belongs in the Window\'s title. setTitleSupplier computes the title, and window.bind connects quantity changes to updateTitle().","sidebar":"tutorialSidebar"},"signal-ui/visual":{"id":"signal-ui/visual","title":"Visual layers","description":"Slot five of the product menu normally shows a diamond. Clicking the marking toggle in the bottom-right should turn slot five into an emerald; clicking again restores the diamond. Only the display changes: clicking slot five still runs the original diamond button\'s handler.","sidebar":"tutorialSidebar"},"signal/async":{"id":"signal/async","title":"Async loading","description":"A player opens the shop and the menu needs to show the account balance, but the balance lives in a database and the query can take a few hundred milliseconds. The menu should show \\"Loading\\" first and the balance once the query lands; code reading the menu\'s state meanwhile keeps running.","sidebar":"tutorialSidebar"},"signal/basics":{"id":"signal/basics","title":"Signal basics","description":"A Signal holds changing data and can compute new values from it. It works fine in plain business code, with menus reading and displaying it on top.","sidebar":"tutorialSidebar"},"signal/collections":{"id":"signal/collections","title":"Collection state","description":"A shop menu starts out selling apples and bread. An admin lists diamonds and the product list gains an entry while the \\"number of products\\" counter moves with it; removing apples updates both places again.","sidebar":"tutorialSidebar"},"signal/derive":{"id":"signal/derive","title":"Deriving and combining","description":"A buy button may depend on the quantity, the unit price, and the balance all at once; switching a category makes the menu read a different source. Derived Signals can combine these inputs and also control when change notifications fire.","sidebar":"tutorialSidebar"},"signal/partitions":{"id":"signal/partitions","title":"Partition state","description":"The shop\'s apples and bread each have their own stock. Viewing the apple detail page cares about apples only; selling one bread should not force a re-read of apple stock.","sidebar":"tutorialSidebar"},"signal/polling":{"id":"signal/polling","title":"Polling","description":"The shop shows the server-wide remaining stock, which lives in a database that other subservers also sell from. This server never sees every purchase event, so relying on local dirty() calls alone cannot keep the display current.","sidebar":"tutorialSidebar"},"signal/why":{"id":"signal/why","title":"Why Signals","description":"The data a menu shows changes: a boss\'s health is dropping, a player\'s coins just arrived, a few units of a product sold. A Signal holds a changing value and notifies its dependents when it changes, so they can redraw. The menus built from fixed data in the previous chapters follow the data automatically once a Signal is attached.","sidebar":"tutorialSidebar"},"visual/animation":{"id":"visual/animation","title":"Animations","description":"An animation changes a slot\'s display frame by frame for a while, then the original look returns. Like visual layers, it changes only the display: real items stay untouched, and clicks are unaffected.","sidebar":"tutorialSidebar"},"visual/layers":{"id":"visual/layers","title":"Visual layers","description":"Visual layers decide how a slot looks, without touching the real item in it. What the player sees comes from the visual layer; clicks, shift transfers, code reads, and events all keep using the real item.","sidebar":"tutorialSidebar"},"window/data":{"id":"window/data","title":"Window data","description":"A Window can carry business objects for click handlers to read. This page also covers client state confirmation and the cursor data and cancellation in outside-click events.","sidebar":"tutorialSidebar"},"window/layout":{"id":"window/layout","title":"Window layouts","description":"The top of a Window is the container; the bottom is the player inventory. The bottom is fixed: three rows of main storage plus one hotbar row, 36 slots in total. You can lay out only the top menu, or put menu content in the bottom as well.","sidebar":"tutorialSidebar"},"window/lifecycle":{"id":"window/lifecycle","title":"Opening and closing","description":"A Window presents a Pane to one player and owns opening, closing, and player interaction in between. Each menu open usually creates a fresh Window; the Pane can be shared as needed.","sidebar":"tutorialSidebar"},"window/title":{"id":"window/title","title":"Window titles","description":"A Window\'s title can be fixed text or generated from business data. After the menu opens, the title can still be updated through the Window.","sidebar":"tutorialSidebar"},"window/types":{"id":"window/types","title":"Window types","description":"Sparrow UI covers 17 vanilla container windows. A regular chest suits free-form layouts; when you need text input, a progress bar, or a trade list, pick a window that ships with those widgets.","sidebar":"tutorialSidebar"}}}}')}}]);